template<class F>void Until(F f,lab::VirtualSessionController& c,bool allowError=false,int seconds=120){auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(seconds);while(!f()){Pump();if(c.State()==lab::SessionState::Error && !allowError)throw std::runtime_error(c.Error()+" "+c.BuildResult().dump());if(std::chrono::steady_clock::now()>deadline)throw std::runtime_error("GUI timeout: "+c.Frame().dump());}for(int n=0;n<3;++n)Pump();}
Json Read(const fs::path& p){std::ifstream input(p);Json result;input>>result;return result;}
